package com.edubridge.chat;
import com.edubridge.auth.UserAccount; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="chat_messages",indexes={@Index(name="idx_message_channel_created",columnList="channel_id,created_at")}) public class ChatMessage { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) private ChatChannel channel; @ManyToOne(optional=false) private UserAccount sender; @Column(nullable=false,length=4000) private String content; @Column(nullable=false) private Instant createdAt=Instant.now(); private Instant editedAt; protected ChatMessage(){} public ChatMessage(ChatChannel c,UserAccount s,String text){channel=c;sender=s;content=text;} public UUID getId(){return id;} public ChatChannel getChannel(){return channel;} public UserAccount getSender(){return sender;} public String getContent(){return content;} public Instant getCreatedAt(){return createdAt;} public Instant getEditedAt(){return editedAt;} public void edit(String s){content=s;editedAt=Instant.now();} }
